class Task:
    def __init__(self, title, priority=2):
        self.title = title
        self.priority = priority
        self.done = False

    def complete(self):
        self.done = True


class TaskList:
    def __init__(self):
        self.tasks = []

    def add(self, task):
        self.tasks.append(task)

    def pending(self):
        return [t.title for t in self.tasks if not t.done]

