class Post:
    def __init__(self, title, text):
        self.title = title
        self.text = text
        self.slug = title.lower().replace(" ", "-")

    def word_count(self):
        return len(self.text.split())


class Site:
    def __init__(self, title):
        self.title = title
        self.posts = []

    def add(self, post):
        self.posts.append(post)

    def total_words(self):
        return sum(post.word_count() for post in self.posts)

