class Course:
    def __init__(self, name, hours):
        self.name = name
        self.hours = hours
        self.grades = []

    def add_grade(self, grade):
        self.grades.append(grade)

    def average(self):
        if len(self.grades) == 0:
            return 0
        return round(sum(self.grades) / len(self.grades), 2)

    def passed(self):
        return self.average() >= 50
